    31→
    32→// Account is the Ethereum consensus representation of accounts.
    33→// These objects are stored in the main account trie.
    34→// DESCRIBED: docs/programmers_guide/guide.md#ethereum-state
    35→type Account struct {
    36→	Initialised     bool
    37→	Nonce           uint64
    38→	Balance         uint256.Int
    39→	Root            common.Hash // merkle root of the storage trie
    40→	CodeHash        common.Hash // hash of the bytecode
    41→	Incarnation     uint64
    42→	PrevIncarnation uint64
    43→}
    44→
    45→const (
    46→	MimetypeDataWithValidator = "data/validator"
    47→	MimetypeTypedData         = "data/typed"
    48→	MimetypeClique            = "application/x-clique-header"
    49→	MimetypeBor               = "application/x-bor-header"
    50→	MimetypeTextPlain         = "text/plain"
    51→)
    52→
    53→// NewAccount creates a new account w/o code nor storage.
    54→func NewAccount() Account {
    55→	return Account{
    56→		Root:     empty.RootHash,
    57→		CodeHash: empty.CodeHash,
    58→	}
    59→}
    60→
    61→func (a *Account) EncodingLengthForStorage() uint {
    62→	var structLength uint = 1 // 1 byte for fieldset
    63→
    64→	if !a.Balance.IsZero() {
    65→		structLength += uint(a.Balance.ByteLen()) + 1
    66→	}
    67→
    68→	if a.Nonce > 0 {
    69→		structLength += uint(common.BitLenToByteLen(bits.Len64(a.Nonce))) + 1
    70→	}
    71→
    72→	if !a.IsEmptyCodeHash() {
    73→		structLength += 33 // 32-byte array + 1 bytes for length
    74→	}
    75→
    76→	if a.Incarnation > 0 {
    77→		structLength += uint(common.BitLenToByteLen(bits.Len64(a.Incarnation))) + 1
    78→	}
    79→
    80→	return structLength
    81→}
    82→
    83→func (a *Account) EncodingLengthForHashing() uint {
    84→	balanceBytes := 0
    85→	if !a.Balance.LtUint64(128) {
    86→		balanceBytes = a.Balance.ByteLen()
    87→	}
    88→
    89→	nonceBytes := rlp.IntLenExcludingHead(a.Nonce)
    90→
    91→	structLength := balanceBytes + nonceBytes + 2
    92→
    93→	structLength += 66 // Two 32-byte arrays + 2 prefixes
    94→
    95→	return uint(rlp.ListPrefixLen(structLength) + structLength)
    96→}
    97→
    98→func (a *Account) EncodeForStorage(buffer []byte) {
    99→	var fieldSet = 0 // start with first bit set to 0
   100→	var pos = 1
   101→	if a.Nonce > 0 {
   102→		fieldSet = 1
   103→		nonceBytes := common.BitLenToByteLen(bits.Len64(a.Nonce))
   104→		buffer[pos] = byte(nonceBytes)
   105→		var nonce = a.Nonce
   106→		for i := nonceBytes; i > 0; i-- {
   107→			buffer[pos+i] = byte(nonce)
   108→			nonce >>= 8
   109→		}
   110→		pos += nonceBytes + 1
   111→	}
   112→
   113→	// Encoding balance
   114→	if !a.Balance.IsZero() {
   115→		fieldSet |= 2
   116→		balanceBytes := a.Balance.ByteLen()
   117→		buffer[pos] = byte(balanceBytes)
   118→		pos++
   119→		a.Balance.WriteToSlice(buffer[pos : pos+balanceBytes])
   120→		pos += balanceBytes
   121→	}
   122→
   123→	if a.Incarnation > 0 {
   124→		fieldSet |= 4
   125→		incarnationBytes := common.BitLenToByteLen(bits.Len64(a.Incarnation))
   126→		buffer[pos] = byte(incarnationBytes)
   127→		var incarnation = a.Incarnation
   128→		for i := incarnationBytes; i > 0; i-- {
   129→			buffer[pos+i] = byte(incarnation)
   130→			incarnation >>= 8
   131→		}
   132→		pos += incarnationBytes + 1
   133→	}
   134→
   135→	// Encoding CodeHash
   136→	if !a.IsEmptyCodeHash() {
   137→		fieldSet |= 8
   138→		buffer[pos] = 32
   139→		copy(buffer[pos+1:], a.CodeHash.Bytes())
   140→		//pos += 33
   141→	}
   142→
   143→	buffer[0] = byte(fieldSet)
   144→}
   145→
   146→// Decodes length and determines whether it corresponds to a structure of a byte array
   147→func decodeLengthForHashing(buffer []byte, pos int) (length int, structure bool, newPos int) {
   148→	switch firstByte := int(buffer[pos]); {
   149→	case firstByte < 128:
   150→		return 0, false, pos
   151→	case firstByte < 184:
   152→		return firstByte - 128, false, pos + 1
   153→	case firstByte < 192:
   154→		// Next byte is the length of the length + 183
   155→		lenEnd := pos + 1 + firstByte - 183
   156→		for i := pos + 1; i < lenEnd; i++ {
   157→			length = (length << 8) + int(buffer[i])
   158→		}
   159→		return length, false, lenEnd
   160→	case firstByte < 248:
   161→		return firstByte - 192, true, pos + 1
   162→	default:
   163→		// Next byte is the length of the length + 247
   164→		lenEnd := pos + 1 + firstByte - 247
   165→		for i := pos + 1; i < lenEnd; i++ {
   166→			length = (length << 8) + int(buffer[i])
   167→		}
   168→		return length, true, lenEnd
   169→	}
   170→}
   171→
   172→var rlpEncodingBufPool = sync.Pool{
   173→	New: func() interface{} {
   174→		buf := make([]byte, 0, 128)
   175→		return &buf
   176→	},
   177→}
   178→
   179→func (a *Account) EncodeRLP(w io.Writer) error {
   180→	var buf []byte
   181→	l := a.EncodingLengthForHashing()
   182→	if l > 128 {
   183→		buf = make([]byte, l)
   184→	} else {
   185→		bp := rlpEncodingBufPool.Get().(*[]byte)
   186→		defer rlpEncodingBufPool.Put(bp)
   187→		buf = *bp
   188→		buf = buf[:l]
   189→	}
   190→
   191→	a.EncodeForHashing(buf)
   192→	_, err := w.Write(buf)
   193→	return err
   194→}
   195→
   196→// returns the RLP encoding of the account directly as a []byte
   197→func (a *Account) RLP() []byte {
   198→	accRlp := make([]byte, a.EncodingLengthForHashing())
   199→	a.EncodeForHashing(accRlp)
   200→	return accRlp
   201→}
   202→
   203→func (a *Account) EncodeForHashing(buffer []byte) {
   204→	balanceBytes := 0
   205→	if !a.Balance.LtUint64(128) {
   206→		balanceBytes = a.Balance.ByteLen()
   207→	}
   208→
   209→	nonceBytes := rlp.IntLenExcludingHead(a.Nonce)
   210→
   211→	var structLength = uint(balanceBytes + nonceBytes + 2)
   212→	structLength += 66 // Two 32-byte arrays + 2 prefixes
   213→
   214→	var pos int
   215→	if structLength < 56 {
   216→		buffer[0] = byte(192 + structLength)
   217→		pos = 1
   218→	} else {
   219→		lengthBytes := common.BitLenToByteLen(bits.Len(structLength))
   220→		buffer[0] = byte(247 + lengthBytes)
   221→
   222→		for i := lengthBytes; i > 0; i-- {
   223→			buffer[i] = byte(structLength)
   224→			structLength >>= 8
   225→		}
   226→
   227→		pos = lengthBytes + 1
   228→	}
   229→
   230→	// Encoding nonce
   231→	if a.Nonce < 128 && a.Nonce != 0 {
   232→		buffer[pos] = byte(a.Nonce)
   233→	} else {
   234→		buffer[pos] = byte(128 + nonceBytes)
   235→		var nonce = a.Nonce
   236→		for i := nonceBytes; i > 0; i-- {
   237→			buffer[pos+i] = byte(nonce)
   238→			nonce >>= 8
   239→		}
   240→	}
   241→	pos += 1 + nonceBytes
   242→
   243→	// Encoding balance
   244→	if a.Balance.LtUint64(128) && !a.Balance.IsZero() {
   245→		buffer[pos] = byte(a.Balance.Uint64())
   246→		pos++
   247→	} else {
   248→		buffer[pos] = byte(128 + balanceBytes)
   249→		pos++
   250→		a.Balance.WriteToSlice(buffer[pos : pos+balanceBytes])
   251→		pos += balanceBytes
   252→	}
   253→
   254→	// Encoding Root and CodeHash
   255→	buffer[pos] = 128 + 32
   256→	pos++
   257→	copy(buffer[pos:], a.Root[:])
   258→	pos += 32
   259→	buffer[pos] = 128 + 32
   260→	pos++
   261→	copy(buffer[pos:], a.CodeHash[:])
   262→	//pos += 32
   263→}
   264→
   265→// Copy makes `a` a full, independent (meaning that if the `image` changes in any way, it does not affect `a`) copy of the account `image`.
   266→func (a *Account) Copy(image *Account) {
   267→	a.Initialised = image.Initialised
   268→	a.Nonce = image.Nonce
   269→	a.Balance.Set(&image.Balance)
   270→	copy(a.Root[:], image.Root[:])
   271→	copy(a.CodeHash[:], image.CodeHash[:])
   272→	a.Incarnation = image.Incarnation
   273→}
   274→
   275→func (a *Account) DecodeForHashing(enc []byte) error {
   276→	length, structure, pos := decodeLengthForHashing(enc, 0)
   277→	if pos+length != len(enc) {
   278→		return fmt.Errorf(
   279→			"malformed RLP for Account(%x): prefixLength(%d) + dataLength(%d) != sliceLength(%d)",
   280→			enc, pos, length, len(enc))
   281→	}
   282→	if !structure {
   283→		return fmt.Errorf(
   284→			"encoding of Account should be RLP struct, got byte array: %x",
   285→			enc,
   286→		)
   287→	}
   288→
   289→	a.Initialised = true
   290→	a.Nonce = 0
   291→	a.Balance.Clear()
   292→	a.Root = empty.RootHash
   293→	a.CodeHash = empty.CodeHash
   294→	if length == 0 && structure {
   295→		return nil
   296→	}
   297→
   298→	if pos < len(enc) {
   299→		nonceBytes, s, newPos := decodeLengthForHashing(enc, pos)
   300→		if s {
   301→			return fmt.Errorf(
   302→				"encoding of Account.Nonce should be byte array, got RLP struct: %x",
   303→				enc[pos:newPos+nonceBytes],
   304→			)
   305→		}
   306→
   307→		if newPos+nonceBytes > len(enc) {
   308→			return fmt.Errorf(
   309→				"malformed RLP for Account.Nonce(%x): prefixLength(%d) + dataLength(%d) >= sliceLength(%d)",
   310→				enc[pos:newPos+nonceBytes],
   311→				newPos-pos, nonceBytes, len(enc)-pos,
   312→			)
   313→		}
   314→
   315→		var nonce uint64
   316→		if nonceBytes == 0 && newPos == pos {
   317→			nonce = uint64(enc[newPos])
   318→			pos = newPos + 1
   319→		} else {
   320→			for _, b := range enc[newPos : newPos+nonceBytes] {
   321→				nonce = (nonce << 8) + uint64(b)
   322→			}
   323→			pos = newPos + nonceBytes
   324→		}
   325→
   326→		a.Nonce = nonce
   327→	}
   328→	if pos < len(enc) {
   329→		balanceBytes, s, newPos := decodeLengthForHashing(enc, pos)
   330→		if s {
   331→			return fmt.Errorf(
   332→				"encoding of Account.Balance should be byte array, got RLP struct: %x",
   333→				enc[pos:newPos+balanceBytes],
   334→			)
   335→		}
   336→
   337→		if newPos+balanceBytes > len(enc) {
   338→			return fmt.Errorf("malformed RLP for Account.Balance(%x): prefixLength(%d) + dataLength(%d) >= sliceLength(%d)",
   339→				enc[pos],
   340→				newPos-pos, balanceBytes, len(enc)-pos,
   341→			)
   342→		}
   343→
   344→		if balanceBytes == 0 && newPos == pos {
   345→			a.Balance.SetUint64(uint64(enc[newPos]))
   346→			pos = newPos + 1
   347→		} else {
   348→			a.Balance.SetBytes(enc[newPos : newPos+balanceBytes])
   349→			pos = newPos + balanceBytes
   350→		}
   351→	}
   352→	if pos < len(enc) {
   353→		rootBytes, s, newPos := decodeLengthForHashing(enc, pos)
   354→		if s {
   355→			return fmt.Errorf(
   356→				"encoding of Account.Root should be byte array, got RLP struct: %x",
   357→				enc[pos:newPos+rootBytes],
   358→			)
   359→		}
   360→
   361→		if rootBytes != 32 {
   362→			return fmt.Errorf(
   363→				"encoding of Account.Root should have size 32, got %d",
   364→				rootBytes,
   365→			)
   366→		}
   367→
   368→		if newPos+rootBytes > len(enc) {
   369→			return fmt.Errorf("malformed RLP for Account.Root(%x): prefixLength(%d) + dataLength(%d) >= sliceLength(%d)",
   370→				enc[pos],
   371→				newPos-pos, rootBytes, len(enc)-pos,
   372→			)
   373→		}
   374→
   375→		copy(a.Root[:], enc[newPos:newPos+rootBytes])
   376→		pos = newPos + rootBytes
   377→	}
   378→
   379→	if pos < len(enc) {
   380→		codeHashBytes, s, newPos := decodeLengthForHashing(enc, pos)
   381→		if s {
   382→			return fmt.Errorf(
   383→				"encoding of Account.CodeHash should be byte array, got RLP struct: %x",
   384→				enc[pos:newPos+codeHashBytes],
   385→			)
   386→		}
   387→
   388→		if codeHashBytes != 32 {
   389→			return fmt.Errorf(
   390→				"encoding of Account.CodeHash should have size 32, got %d",
   391→				codeHashBytes,
   392→			)
   393→		}
   394→
   395→		if newPos+codeHashBytes > len(enc) {
   396→			return fmt.Errorf("malformed RLP for Account.CodeHash(%x): prefixLength(%d) + dataLength(%d) >= sliceLength(%d)",
   397→				enc[pos:newPos+codeHashBytes],
   398→				newPos-pos, codeHashBytes, len(enc)-pos,
   399→			)
   400→		}
   401→
   402→		copy(a.CodeHash[:], enc[newPos:newPos+codeHashBytes])
   403→		pos = newPos + codeHashBytes
   404→	}
   405→
   406→	if pos < len(enc) {
   407→		storageSizeBytes, s, newPos := decodeLengthForHashing(enc, pos)
   408→		if s {
   409→			return fmt.Errorf(
   410→				"encoding of Account.StorageSize should be byte array, got RLP struct: %x",
   411→				enc[pos:newPos+storageSizeBytes],
   412→			)
   413→		}
   414→
   415→		if newPos+storageSizeBytes > len(enc) {
   416→			return fmt.Errorf(
   417→				"malformed RLP for Account.StorageSize(%x): prefixLength(%d) + dataLength(%d) >= sliceLength(%d)",
   418→				enc[pos:newPos+storageSizeBytes],
   419→				newPos-pos, storageSizeBytes, len(enc)-pos,
   420→			)
   421→		}
   422→
   423→		// Commented out because of the ineffectual assignment - uncomment if adding more fields
   424→		var storageSize uint64
   425→		if storageSizeBytes == 0 && newPos == pos {
   426→			storageSize = uint64(enc[newPos])
   427→			pos = newPos + 1
   428→		} else {
   429→			for _, b := range enc[newPos : newPos+storageSizeBytes] {
   430→				storageSize = (storageSize << 8) + uint64(b)
   431→			}
   432→			pos = newPos + storageSizeBytes
   433→		}
   434→		_ = storageSize
   435→	}
   436→	_ = pos
   437→
   438→	return nil
   439→}
   440→
   441→func (a *Account) Reset() {
   442→	a.Initialised = true
   443→	a.Nonce = 0
   444→	a.Incarnation = 0
   445→	a.Balance.Clear()
   446→	a.Root = empty.RootHash
   447→	a.CodeHash = empty.CodeHash
   448→}
   449→
   450→func (a *Account) DecodeForStorage(enc []byte) error {
   451→	a.Reset()
   452→
   453→	if len(enc) == 0 {
   454→		return nil
   455→	}
   456→
   457→	var fieldSet = enc[0]
   458→	var pos = 1
   459→
   460→	if fieldSet&1 > 0 {
   461→		decodeLength := int(enc[pos])
   462→
   463→		if len(enc) < pos+decodeLength+1 {
   464→			return fmt.Errorf(
   465→				"malformed CBOR for Account.Nonce: %s, Length %d",
   466→				enc[pos+1:], decodeLength)
   467→		}
   468→
   469→		a.Nonce = common.BytesToUint64(enc[pos+1 : pos+decodeLength+1])
   470→		pos += decodeLength + 1
   471→	}
   472→
   473→	if fieldSet&2 > 0 {
   474→		decodeLength := int(enc[pos])
   475→
   476→		if len(enc) < pos+decodeLength+1 {
   477→			return fmt.Errorf(
   478→				"malformed CBOR for Account.Nonce: %s, Length %d",
   479→				enc[pos+1:], decodeLength)
   480→		}
   481→
   482→		a.Balance.SetBytes(enc[pos+1 : pos+decodeLength+1])
   483→		pos += decodeLength + 1
   484→	}
   485→
   486→	if fieldSet&4 > 0 {
   487→		decodeLength := int(enc[pos])
   488→
   489→		if len(enc) < pos+decodeLength+1 {
   490→			return fmt.Errorf(
   491→				"malformed CBOR for Account.Incarnation: %s, Length %d",
   492→				enc[pos+1:], decodeLength)
   493→		}
   494→
   495→		a.Incarnation = common.BytesToUint64(enc[pos+1 : pos+decodeLength+1])
   496→		pos += decodeLength + 1
   497→	}
   498→
   499→	if fieldSet&8 > 0 {
   500→
   501→		decodeLength := int(enc[pos])
   502→
   503→		if decodeLength != 32 {
   504→			return fmt.Errorf("codehash should be 32 bytes long, got %d instead",
   505→				decodeLength)
   506→		}
   507→
   508→		if len(enc) < pos+decodeLength+1 {
   509→			return fmt.Errorf(
   510→				"malformed CBOR for Account.CodeHash: %s, Length %d",
   511→				enc[pos+1:], decodeLength)
   512→		}
   513→
   514→		a.CodeHash.SetBytes(enc[pos+1 : pos+decodeLength+1])
   515→		pos += decodeLength + 1
   516→	}
   517→
   518→	_ = pos
   519→
   520→	return nil
   521→}
   522→
   523→func DecodeIncarnationFromStorage(enc []byte) (uint64, error) {
   524→	if len(enc) == 0 {
   525→		return 0, nil
   526→	}
   527→
   528→	var fieldSet = enc[0]
   529→	var pos = 1
   530→
   531→	//looks for the position incarnation is at
   532→	if fieldSet&1 > 0 {
   533→		decodeLength := int(enc[pos])
   534→		if len(enc) < pos+decodeLength+1 {
   535→			return 0, fmt.Errorf(
   536→				"malformed CBOR for Account.Nonce: %s, Length %d",
   537→				enc[pos+1:], decodeLength)
   538→		}
   539→		pos += decodeLength + 1
   540→	}
   541→
   542→	if fieldSet&2 > 0 {
   543→		decodeLength := int(enc[pos])
   544→		if len(enc) < pos+decodeLength+1 {
   545→			return 0, fmt.Errorf(
   546→				"malformed CBOR for Account.Nonce: %s, Length %d",
   547→				enc[pos+1:], decodeLength)
   548→		}
   549→		pos += decodeLength + 1
   550→	}
   551→
   552→	if fieldSet&4 > 0 {
   553→		decodeLength := int(enc[pos])
   554→
   555→		//checks if the ending position is correct if not returns 0
   556→		if len(enc) < pos+decodeLength+1 {
   557→			return 0, fmt.Errorf(
   558→				"malformed CBOR for Account.Incarnation: %s, Length %d",
   559→				enc[pos+1:], decodeLength)
   560→		}
   561→
   562→		incarnation := common.BytesToUint64(enc[pos+1 : pos+decodeLength+1])
   563→		return incarnation, nil
   564→	}
   565→
   566→	return 0, nil
   567→
   568→}
