   576→func (a *Account) DecodeRLP(s *rlp.Stream) error {
   577→	raw, err := s.Raw()
   578→	if err != nil {
   579→		return err
   580→	}
   581→
   582→	err = a.DecodeForHashing(raw)
   583→	return err
