   613→func ConvertV3toV2(v []byte) ([]byte, error) {
   614→	var a Account
   615→	if err := DeserialiseV3(&a, v); err != nil {
   616→		return nil, fmt.Errorf("ConvertV3toV2(%x): %w", v, err)
   617→	}
   618→	v = make([]byte, a.EncodingLengthForStorage())
   619→	a.EncodeForStorage(v)
   620→	return v, nil
