   623→// DeserialiseV3 - method to deserialize accounts in Erigon22 history
   624→func DeserialiseV3(a *Account, enc []byte) error {
   625→	a.Reset()
   626→	//if len(enc) == 0 {
   627→	//	return nil
   628→	//}
   629→	pos := 0
   630→	nonceBytes := int(enc[pos])
   631→	pos++
   632→	if nonceBytes > 0 {
   633→		a.Nonce = common.BytesToUint64(enc[pos : pos+nonceBytes])
   634→		pos += nonceBytes
   635→	}
   636→	balanceBytes := int(enc[pos])
   637→	pos++
   638→	if balanceBytes > 0 {
   639→		a.Balance.SetBytes(enc[pos : pos+balanceBytes])
   640→		pos += balanceBytes
   641→	}
   642→	codeHashBytes := int(enc[pos])
   643→	pos++
   644→	if codeHashBytes > 0 {
   645→		copy(a.CodeHash[:], enc[pos:pos+codeHashBytes])
   646→		pos += codeHashBytes
   647→	}
   648→	if pos >= len(enc) {
   649→		return fmt.Errorf("deserialse2: %d >= %d ", pos, len(enc))
   650→	}
   651→	incBytes := int(enc[pos])
   652→	pos++
   653→	if incBytes > 0 {
   654→		a.Incarnation = common.BytesToUint64(enc[pos : pos+incBytes])
   655→	}
   656→	return nil
   657→}
   658→
   659→func SerialiseV3(a *Account) []byte {
   660→	var l int
   661→	l++
   662→	if a.Nonce > 0 {
   663→		l += common.BitLenToByteLen(bits.Len64(a.Nonce))
   664→	}
   665→	l++
   666→	if !a.Balance.IsZero() {
   667→		l += a.Balance.ByteLen()
   668→	}
   669→	l++
   670→	if !a.IsEmptyCodeHash() {
   671→		l += 32
   672→	}
   673→	l++
   674→	if a.Incarnation > 0 {
   675→		l += common.BitLenToByteLen(bits.Len64(a.Incarnation))
   676→	}
   677→	value := make([]byte, l)
   678→	pos := 0
   679→	if a.Nonce == 0 {
   680→		value[pos] = 0
   681→		pos++
   682→	} else {
   683→		nonceBytes := common.BitLenToByteLen(bits.Len64(a.Nonce))
   684→		value[pos] = byte(nonceBytes)
   685→		var nonce = a.Nonce
   686→		for i := nonceBytes; i > 0; i-- {
   687→			value[pos+i] = byte(nonce)
   688→			nonce >>= 8
   689→		}
   690→		pos += nonceBytes + 1
   691→	}
   692→	if a.Balance.IsZero() {
   693→		value[pos] = 0
   694→		pos++
   695→	} else {
   696→		balanceBytes := a.Balance.ByteLen()
   697→		value[pos] = byte(balanceBytes)
   698→		pos++
   699→		a.Balance.WriteToSlice(value[pos : pos+balanceBytes])
   700→		pos += balanceBytes
   701→	}
   702→	if a.IsEmptyCodeHash() {
   703→		value[pos] = 0
   704→		pos++
   705→	} else {
   706→		value[pos] = 32
   707→		pos++
   708→		copy(value[pos:pos+32], a.CodeHash[:])
   709→		pos += 32
   710→	}
   711→	if a.Incarnation == 0 {
   712→		value[pos] = 0
   713→	} else {
   714→		incBytes := common.BitLenToByteLen(bits.Len64(a.Incarnation))
   715→		value[pos] = byte(incBytes)
   716→		var inc = a.Incarnation
   717→		for i := incBytes; i > 0; i-- {
   718→			value[pos+i] = byte(inc)
   719→			inc >>= 8
   720→		}
   721→	}
   722→	return value
   723→}
   724→
   725→func SerialiseV3Len(a *Account) (l int) {
   726→	l++
